<?php $t = $task ?? []; ?>
<form method="post" class="card max-w-4xl"><?= csrf_field() ?><div class="mb-6 flex items-center justify-between"><div><h1 class="text-3xl font-bold tracking-[-.025em]"><?= esc($title) ?></h1><p class="text-slate-500">Task details and assignment.</p></div><a href="<?= site_url('admin/tasks') ?>" class="btn btn-ghost">Back</a></div><div class="grid gap-4 md:grid-cols-2"><div class="md:col-span-2"><label class="label">Title</label><input class="field" name="title" value="<?= esc(old('title', $t['title'] ?? '')) ?>"></div><div><label class="label">Category</label><select class="field" name="category"><?php foreach (['Feeding','Cleaning','Medical','Transport','Socialization','Walking','Adoption'] as $s): ?><option <?= old('category', $t['category'] ?? '')===$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select></div><div><label class="label">Priority</label><select class="field" name="priority"><?php foreach (['Low','Medium','High'] as $s): ?><option <?= old('priority', $t['priority'] ?? '')===$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select></div><div><label class="label">Status</label><select class="field" name="status"><?php foreach (['Pending','In Progress','Completed'] as $s): ?><option <?= old('status', $t['status'] ?? '')===$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select></div><div><label class="label">Location</label><input class="field" name="location" value="<?= esc(old('location', $t['location'] ?? '')) ?>"></div><div><label class="label">Date</label><input type="date" class="field" name="task_date" value="<?= esc(old('task_date', $t['task_date'] ?? date('Y-m-d'))) ?>"></div><div><label class="label">Time</label><input type="time" class="field" name="task_time" value="<?= esc(old('task_time', substr((string)($t['task_time'] ?? '08:00'),0,5)) ) ?>"></div><div><label class="label">Assign To</label><select class="field" name="assigned_to"><option value="">Unassigned</option><?php foreach ($volunteers as $v): ?><?php $availability = trim((string) ($v['availability'] ?? '')); $hours = trim(substr((string) ($v['availability_start_time'] ?? ''), 0, 5) . '–' . substr((string) ($v['availability_end_time'] ?? ''), 0, 5), '–'); ?><option value="<?= $v['id'] ?>" <?= (string)old('assigned_to', $t['assigned_to'] ?? '')===(string)$v['id']?'selected':'' ?> <?= ($v['status'] ?? '') !== 'Active' ? 'disabled' : '' ?>><?= esc($v['name']) ?><?= $availability ? ' — ' . esc($availability) : ' — availability not set' ?><?= $hours ? ' (' . esc($hours) . ')' : '' ?><?= ($v['status'] ?? '') !== 'Active' ? ' — unavailable' : '' ?></option><?php endforeach; ?></select><p class="mt-1 text-xs text-slate-500">The system verifies the selected volunteer’s day, time, and existing task schedule before saving.</p></div><div><label class="label">Link Cat</label><select class="field" name="animal_id"><option value="">None</option><?php foreach ($animals as $a): ?><option value="<?= $a['id'] ?>" <?= (string)old('animal_id', $t['animal_id'] ?? '')===(string)$a['id']?'selected':'' ?>><?= esc($a['name']) ?></option><?php endforeach; ?></select></div></div><div class="mt-4"><label class="label">Description</label><textarea class="field min-h-32" name="description"><?= esc(old('description', $t['description'] ?? '')) ?></textarea></div><button class="btn btn-primary mt-6">Save Task</button></form>
<?= $this->endSection() ?>
